using System;

namespace GrindHero.Domain.Combat
{
    public static class RecoveryRules
    {
        public static float Heal(float health, float maximumHealth, float perSecond, float seconds)
        {
            if (!IsFinite(health) || !IsFinite(maximumHealth) ||
                !IsFinite(perSecond) || !IsFinite(seconds) ||
                health < 0f || maximumHealth <= 0f || health > maximumHealth ||
                perSecond < 0f || seconds < 0f)
            {
                throw new ArgumentOutOfRangeException(nameof(health), "Invalid healing inputs.");
            }

            return health == 0f ? 0f : (float)Math.Min(maximumHealth, health + (double)perSecond * seconds);
        }

        private static bool IsFinite(float value)
        {
            return !float.IsNaN(value) && !float.IsInfinity(value);
        }
    }
}
